cypress_script:
describe('Broken Images Page Accessibility Tests', () => {
  it('should display the title and heading correctly', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.title().should('eq', 'The Internet');
    cy.get('h1').contains('Broken Images');
  });
  it('should not display any images', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('#content').should('contain.text', 'Broken Images');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Broken Images Page Accessibility Tests', () => {
  test('should display the title and heading correctly', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    expect(await page.title()).toBe('The Internet');
    await expect(page.locator('h1')).toHaveText('Broken Images');
  });
  test('should not display any images', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    await expect(page.locator('#content')).toContainText('Broken Images');
  });
});
